<script lang="ts">
	import { goto } from "$app/navigation";
	import Button from "$lib/components/ui/button/button.svelte";
	import * as Pagination from "$lib/components/ui/pagination";
	import { EllipsisIcon } from "@lucide/svelte";

	const {
		feed,
		onPaginate
	}: {
		feed: FeedResponse<any>;
		onPaginate?: () => void;
	} = $props();
	const pages = $derived(Math.ceil(feed.total / feed.limit));

	const makePath = (page: number) => {
		page = Math.min(Math.max(page, 1), pages);
		const searchParams = new URLSearchParams(window.location.search);
		if (page > 1) searchParams.set("page", page.toString());
		else searchParams.delete("page");
		return window.location.pathname + searchParams.toString();
	};
</script>

<Pagination.Root count={feed.total} perPage={feed.limit} page={feed.page}>
	{#snippet children({ pages: items, currentPage })}
		<Pagination.Content>
			{#each items as page (page.key)}
				{#if page.type === "ellipsis"}
					<Pagination.Item>
						<Button
							type="button"
							variant="ghost"
							size="icon"
							onclick={async () => {
								const value = (prompt("Enter page number") || "").trim();
								if (!value) {
									return;
								}

								const page = Math.min(Math.max(Number(value), 1), pages);
								if (page !== feed.page) {
									await goto(makePath(page));
									onPaginate?.();
								}
							}}
						>
							<EllipsisIcon class="size-4" />
							<span class="sr-only">Jump to page</span>
						</Button>
					</Pagination.Item>
				{:else}
					<Pagination.Item>
						<Pagination.Link class="border-none" {page} isActive={currentPage === page.value} onclick={onPaginate}>
							{#snippet child({ props })}
								<a href={makePath(page.value)} {...props}>
									{page.value}
								</a>
							{/snippet}
						</Pagination.Link>
					</Pagination.Item>
				{/if}
			{/each}
		</Pagination.Content>
	{/snippet}
</Pagination.Root>
